
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_zvpbesol_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_zvpbesol", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-7.322811301005842e-02, -7.220826671298280e-02, -7.074400988529633e-02, -6.864323040785457e-02, -6.563257977342213e-02, -6.132665992174546e-02, -5.519709968821999e-02, -4.659102328040216e-02, -3.506204845446004e-02, -2.213106276490241e-02, -1.945748880840985e-02, -4.448847592160908e-02, -4.903670091734846e-02, -3.765569316759686e-02, -2.488009063795646e-02, -1.816643170059503e-02, -1.769916275529362e-02, -8.247081066264449e-03, -2.295605187484643e-03, -4.421610932074118e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


